const groundBuckets=new Map();
for(const polygon of WEST_WORKSHOPS_WALK_POLYGONS){const xs=polygon.map(p=>p[0]),ys=polygon.map(p=>p[1]);for(let y=Math.floor(Math.min(...ys)/4);y<=Math.floor(Math.max(...ys)/4);y++)for(let x=Math.floor(Math.min(...xs)/4);x<=Math.floor(Math.max(...xs)/4);x++){const key=`${x}/${y}`;if(!groundBuckets.has(key))groundBuckets.set(key,[]);groundBuckets.get(key).push(polygon);}}
function pointInPolygon(p,polygon){let inside=false;for(let i=0,j=polygon.length-1;i<polygon.length;j=i++){const a=polygon[i],b=polygon[j];if((a[1]>p.y)!==(b[1]>p.y)&&p.x<(b[0]-a[0])*(p.y-a[1])/(b[1]-a[1])+a[0])inside=!inside;}return inside;}
export function westWorkshopsPointOpen(p){return Number.isFinite(p?.x)&&Number.isFinite(p?.y)&&(groundBuckets.get(`${Math.floor(p.x/4)}/${Math.floor(p.y/4)}`)||[]).some(polygon=>pointInPolygon(p,polygon));}
const roadGraph=new Map(),nodeKey=p=>`${p.x.toFixed(7)}/${p.y.toFixed(7)}`;
function connect(a,b){const ka=nodeKey(a),kb=nodeKey(b);if(!roadGraph.has(ka))roadGraph.set(ka,{point:a,edges:new Map()});if(!roadGraph.has(kb))roadGraph.set(kb,{point:b,edges:new Map()});const distance=Math.hypot(a.x-b.x,a.y-b.y);roadGraph.get(ka).edges.set(kb,distance);roadGraph.get(kb).edges.set(ka,distance);}
// All intersections are explicit measured centre nodes, shared by the road branches.
for(const road of WEST_WORKSHOPS_ROADS)for(let i=1;i<road.centre.length;i++)connect(road.centre[i-1],road.centre[i]);
function attachment(point){let best=null;for(const road of WEST_WORKSHOPS_ROADS)for(let i=1;i<road.centre.length;i++){const a=road.centre[i-1],b=road.centre[i],dx=b.x-a.x,dy=b.y-a.y,l=dx*dx+dy*dy;if(l<1e-12)continue;const t=Math.max(0,Math.min(1,((point.x-a.x)*dx+(point.y-a.y)*dy)/l)),at={x:a.x+t*dx,y:a.y+t*dy},distance=Math.hypot(point.x-at.x,point.y-at.y);if(!best||distance<best.distance)best={point:at,a,b,distance};}return best;}
const gate=WEST_WORKSHOPS_ROADS[0].centre.at(-1);
/** Public road centres only; the caller validates both endpoint connections and every segment. */
export function courtyardWestWorkshopsPassage(from,to){
 const fromHere=westWorkshopsPointOpen(from),toHere=westWorkshopsPointOpen(to);if(!fromHere&&!toHere)return null;
 const a=attachment(fromHere?from:gate),b=attachment(toHere?to:gate),graph=new Map([...roadGraph].map(([key,node])=>[key,{point:node.point,edges:new Map(node.edges)}]));
 const start='from',finish='to';
 for(const [key,at]of [[start,a],[finish,b]]){graph.set(key,{point:at.point,edges:new Map()});for(const p of [at.a,at.b]){const k=nodeKey(p),d=Math.hypot(p.x-at.point.x,p.y-at.point.y);graph.get(key).edges.set(k,d);graph.get(k).edges.set(key,d);}}
 if(nodeKey(a.a)===nodeKey(b.a)&&nodeKey(a.b)===nodeKey(b.b)){const d=Math.hypot(a.point.x-b.point.x,a.point.y-b.point.y);graph.get(start).edges.set(finish,d);graph.get(finish).edges.set(start,d);}
 const costs=new Map([[start,0]]),previous=new Map(),open=new Set([start]);
 while(open.size){let key=null;for(const k of open)if(key===null||costs.get(k)<costs.get(key))key=k;open.delete(key);if(key===finish)break;for(const [next,d]of graph.get(key).edges){const cost=costs.get(key)+d;if(cost<(costs.get(next)??Infinity)){costs.set(next,cost);previous.set(next,key);open.add(next);}}}
 if(!costs.has(finish))return null;
 const route=[];for(let key=finish;key!==undefined;key=previous.get(key))route.push({...graph.get(key).point});route.reverse();
 return route.filter((p,i)=>!i||Math.hypot(p.x-route[i-1].x,p.y-route[i-1].y)>1e-6);
}
